 ICON.peRecLink=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(20,60,400,60,BLU,8)}${PE_L(20,165,400,165,PE_MUT,3,'stroke-dasharray="10 8"')}${PE_L(20,270,400,270,ORG,8)}${PE_T(20,40,'+V/2',{fs:26,fw:800,fill:BLU})}${PE_T(20,310,'−V/2',{fs:26,fw:800,fill:ORG})}${PE_dbl(210,68,262,GRN,5)}${PE_T(232,150,'V',{fs:40,fw:800,fill:GRN,it:1})}${PE_T(232,196,'pole to pole',{fs:24,fw:800,fill:GRN})}</g>`;
 ICON.peRecSvc=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(10,130,410,130,PE_INK,3)}${PE_bar(30,80,60,BLU,130,1.7)}${PE_bar(170,80,-108.9,ORG,130,1.7)}${PE_bar(310,80,-48.9,GRN,130,1.7)}${PE_T(70,164,'C +60',{fs:24,fw:800,a:'middle',fill:BLU})}${PE_T(210,114,'TCR',{fs:24,fw:800,a:'middle',fill:ORG})}${PE_T(350,114,'net',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
 ICON.peRecStat=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(50,310,50,30,PE_AX,4)}${PE_L(50,310,400,310,PE_AX,4)}${PE_T(36,56,'V',{fs:30,fw:800,a:'end',fill:PE_MUT,it:1})}${PE_T(396,300,'I',{fs:30,fw:800,a:'end',fill:PE_MUT,it:1})}${PE_L(50,310,300,60,ORG,7)}${PE_L(300,60,300,270,GRN,8)}${PE_T(160,150,'SVC',{fs:28,fw:800,a:'end',fill:ORG})}${PE_T(300,298,'STATCOM',{fs:28,fw:800,a:'middle',fill:GRN})}</g>`;
